// 27-tap direct-form FIR, 8-bit samples, unnamed stage (the long named
// inline stage performs the sum over all taps) + register the product to
// go from a register-per-multiply stage to one per stage + pipeline the
// stages (register the stage inputs along with the stage itself, so the
// stage has no dependence on the inputs directly above it).
module firr27_v3 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:26];
    reg  [15:0] s0;
    reg  [15:0] s1;
    reg  [15:0] s2;
    reg  [15:0] s3;
    reg  [15:0] s4;
    reg  [15:0] s5;
    reg  [15:0] s6;
    reg  [15:0] s7;
    reg  [15:0] s8;
    reg  [15:0] s9;
    reg  [15:0] s10;
    reg  [15:0] s11;
    reg  [15:0] s12;
    reg  [15:0] s13;
    reg  [15:0] s14;
    reg  [15:0] s15;
    reg  [15:0] s16;
    reg  [15:0] s17;
    reg  [15:0] s18;
    reg  [15:0] s19;
    reg  [15:0] s20;
    reg  [15:0] s21;
    reg  [15:0] s22;
    reg  [15:0] s23;
    reg  [15:0] s24;
    reg  [15:0] s25;
    reg  [15:0] s26;
    always @(*) s0 = (2*1 + 5)*xs[0];
    always @(*) s1 = (2*2 + 5)*xs[1] + s0;
    always @(*) s2 = (2*3 + 5)*xs[2] + s1;
    always @(*) s3 = (2*4 + 5)*xs[3] + s2;
    always @(*) s4 = (2*5 + 5)*xs[4] + s3;
    always @(*) s5 = (2*6 + 5)*xs[5] + s4;
    always @(*) s6 = (2*7 + 5)*xs[6] + s5;
    always @(*) s7 = (2*8 + 5)*xs[7] + s6;
    always @(*) s8 = (2*9 + 5)*xs[8] + s7;
    always @(*) s9 = (2*10 + 5)*xs[9] + s8;
    always @(*) s10 = (2*11 + 5)*xs[10] + s9;
    always @(*) s11 = (2*12 + 5)*xs[11] + s10;
    always @(*) s12 = (2*13 + 5)*xs[12] + s11;
    always @(*) s13 = (2*14 + 5)*xs[13] + s12;
    always @(*) s14 = (2*15 + 5)*xs[14] + s13;
    always @(*) s15 = (2*16 + 5)*xs[15] + s14;
    always @(*) s16 = (2*17 + 5)*xs[16] + s15;
    always @(*) s17 = (2*18 + 5)*xs[17] + s16;
    always @(*) s18 = (2*19 + 5)*xs[18] + s17;
    always @(*) s19 = (2*20 + 5)*xs[19] + s18;
    always @(*) s20 = (2*21 + 5)*xs[20] + s19;
    always @(*) s21 = (2*22 + 5)*xs[21] + s20;
    always @(*) s22 = (2*23 + 5)*xs[22] + s21;
    always @(*) s23 = (2*24 + 5)*xs[23] + s22;
    always @(*) s24 = (2*25 + 5)*xs[24] + s23;
    always @(*) s25 = (2*26 + 5)*xs[25] + s24;
    always @(*) s26 = (2*27 + 5)*xs[26] + s25;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (int i = 0; i < 27; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (int i = 1; i < 27; i = i + 1) xs[i] <= xs[i-1];
            y <= s26;
        end
    end
endmodule
